"""All public/private declarations in math.h, with explicit arithmetic contracts."""
def register(topic,q,detail):
 def lesson(title,symbol,why,principle,use,reading,qa,cards):
  topic(title,'라이브러리·알고리즘','include/linux/math.h',symbol,why,principle,use,reading,*(q(*x) for x in qa),details=[detail(*x) for x in cards])
 lesson('정렬 올림·낮은 비트를 OR로 채우는 원리','round_up',
  '버퍼 크기나 주소를 특정 2의 거듭제곱 배수에 맞추는 비트 계산을 배웁니다.',
  'round_up(x,y)는 ((x-1)|(y-1))+1이며 y는 양의 2의 거듭제곱입니다. y=8이면 mask=7이 하위 세 비트를 채워 다음 배수 직전까지 올리고 1을 더합니다. __round_mask는 y-1을 x의 자료형으로 변환합니다. 이 연산은 숫자를 거듭제곱 자체로 올리는 roundup_pow_of_two와 달리 고정 단위의 배수를 구합니다.',
  '양수 정렬 단위와 표현 가능한 결과를 확인하고 round_up(19UL,8UL)=24로 사용합니다. signed 최댓값 근처의 x-1·+1 오버플로와 unsigned 결과의 wrap도 caller가 확인합니다.',
  '__round_mask의 typeof와 round_up의 OR·+1을 읽으세요.',
  [('19를 8의 배수로 정렬해 올리면?', '24다','32다','단위 8의 배수는 16,24,32입니다. 19를 수용하는 첫 배수는 24이고 거듭제곱 자체를 찾는 함수가 아닙니다.'),('정렬 단위 6에 이 비트식을 일반 적용해도 되는가?','아니며 양의 2의 거듭제곱 단위가 전제다','모든 양수에서 같은 나눗셈 결과다','하위 비트 mask는 2의 거듭제곱에 맞는 구조입니다. 임의 배수는 roundup의 나눗셈 경로를 사용합니다.')],
  [('평가 횟수','x는 실제 계산에서 한 번, y도 한 번 평가합니다. typeof의 일반 정수 피연산자는 값 평가를 하지 않습니다. 정수식 전제이며 함수 전체의 형식 안전성과는 구분합니다.'),('0의 형식','unsigned x=0은 wrap을 거쳐 결과 0이 될 수 있습니다. signed x=0도 0으로 계산되지만 signed 최솟값의 x-1은 유효하지 않습니다.')])
 lesson('정렬 내림·형식에 맞춘 보수 mask','round_down',
  '정렬 경계 아래 구간을 선택할 때 보수 mask의 폭이 왜 중요한지 배웁니다.',
  'round_down(x,y)는 x & ~__round_mask(x,y)로 y-1의 하위 비트를 지웁니다. __round_mask가 먼저 x의 자료형으로 변환하므로 넓은 x에 좁은 y의 보수를 적용해 높은 비트를 잃는 문제를 피합니다. y는 양의 2의 거듭제곱이고 결과는 같은 단위의 배수입니다.',
  'round_down(19ULL,8U)=16으로 크기를 경계 안에 맞춥니다. rounddown_pow_of_two와 이름·목적을 구분하고 단위 0이나 임의 배수에는 해당 mask 계약을 사용하지 않습니다.',
  '__round_mask의 변환 뒤 ~ 연산과 AND 순서를 읽으세요.',
  [('19를 8의 배수로 정렬 내림하면?','16이다','8이다','19의 하위 세 비트를 지우면 16입니다. 입력을 넘지 않는 가장 가까운 8 배수입니다.'),('mask를 x 형식으로 먼저 변환하는 목적은?','결과 폭에 맞는 보수 mask를 만들기 위해서다','항상 32비트로 줄이기 위해서다','원본 주석은 ~의 폭이 결과 폭과 맞아야 한다고 설명합니다. 넓은 입력의 높은 비트를 유지하는 조건입니다.')],
  [('큰 값 예','round_down((1ULL<<40)+19,8U)는 높은 40번 비트를 유지하며 낮은 부분을 16으로 만듭니다.'),('고정 단위','y=8은 모든 호출의 정렬 단위입니다. 19에서 최대 거듭제곱 16을 고르는 알고리즘과 우연히 같은 결과여도 목적은 다릅니다.')])
 lesson('올림 나눗셈·몫으로 필요한 블록 개수 구하기','DIV_ROUND_UP',
  '전체 데이터를 담기 위해 필요한 고정 크기 블록 수를 올림 나눗셈으로 계산합니다.',
  'DIV_ROUND_UP은 __KERNEL_DIV_ROUND_UP 별칭이며 uapi/linux/const.h의 (n+d-1)/d 식으로 연결됩니다. nonnegative n과 positive d에서 남은 일부 블록을 하나 더 세는 ceil 몫입니다. 덧셈 n+d-1의 표현 가능 범위는 caller 조건이며 일반 오류 반환 분기가 없습니다.',
  '19바이트를 8바이트 블록에 담으면 DIV_ROUND_UP(19U,8U)=3입니다. d=0을 피하고 큰 n에서 중간 합 오버플로를 먼저 확인합니다. d는 식에 두 번 등장하므로 부작용 있는 인수를 넘기지 않습니다.',
  '별칭과 const.h의 실제 산술식을 함께 읽으세요.',
  [('19바이트를 8바이트 블록에 담는 블록 수는?','3개다','2개다','두 블록은 16바이트뿐입니다. 나머지 3바이트를 위한 세 번째 블록이 필요합니다.'),('DIV_ROUND_UP의 divisor에 d++를 넘기는 것은?','반복 평가를 피하도록 먼저 값을 고정해야 한다','매크로가 반드시 한 번만 평가하므로 안전하다','원본 식은 d를 합과 나눗셈에 사용합니다. 반복 부작용과 오버플로 검사는 caller 책임입니다.')],
  [('0개 요청','양수 d에 n=0이면 결과 0입니다. 블록 개수 반환이지 실제 바이트 용량을 반환하지 않습니다.'),('부호 범위','이 올림식은 nonnegative 크기 계산 계약으로 사용합니다. signed 음수의 C 나눗셈이 수학 ceil을 일반 구현한다고 설명하지 않습니다.')])
 lesson('64비트 나눗셈·do_div가 임시 몫을 바꾸는 방식','DIV_ROUND_DOWN_ULL',
  '큰 unsigned 정수를 나눌 때 값과 나머지의 역할을 나눠 읽는 방법을 배웁니다.',
  'DIV_ROUND_DOWN_ULL은 ll을 unsigned long long 임시 _tmp로 복사하고 do_div(_tmp,d)를 실행한 뒤 변경된 _tmp를 반환합니다. do_div는 전달한 피제수를 몫으로 바꾸고 나머지를 반환하는 규약이며 여기서는 나머지를 버립니다. sector_div(a,b)는 이 do_div를 직접 호출하는 별칭이라 caller의 a 자체를 바꿉니다.',
  'do_div에 맞는 nonzero 32비트 divisor와 64비트 unsigned 피제수를 사용합니다. 임시를 만드는 DOWN_ULL과 sector_div의 원본 수정 여부를 구분하고 나머지가 필요한 경우 반환값을 별도로 보관합니다.',
  'statement expression 마지막 _tmp와 sector_div 별칭을 읽으세요.',
  [('DIV_ROUND_DOWN_ULL(19ULL,8U)의 반환은?','몫 2다','나머지 3이다','do_div의 반환인 나머지를 버리고 변경된 임시 몫 2를 반환합니다.'),('a=19에서 sector_div(a,8)의 효과는?','a는 2가 되고 호출 반환은 3이다','a는 유지되고 반환만 2다','별칭은 do_div를 직접 호출합니다. 피제수 수정과 나머지 반환이라는 두 결과를 구분합니다.')],
  [('원본 보존','DOWN_ULL은 ll의 값을 임시에 복사하므로 ll 변수 자체를 do_div로 수정하지 않습니다.'),('아키텍처 연결','do_div의 구현은 asm/div64.h와 대상 아키텍처에 연결됩니다. 이 헤더가 모든 아키텍처의 나눗셈 명령을 직접 구현하는 것은 아닙니다.')])
 lesson('64비트 올림 몫·sector_t의 long 폭 선택','DIV_ROUND_UP_ULL',
  '64비트 크기의 올림 몫과 빌드 폭에 따른 sector 경로를 구분하는 방법을 배웁니다.',
  'DIV_ROUND_UP_ULL은 ll을 unsigned long long으로 변환해 d-1을 더한 후 DOWN_ULL을 호출합니다. 중간 unsigned 합이 wrap되면 원하는 올림 몫이 깨집니다. DIV_ROUND_UP_SECTOR_T는 BITS_PER_LONG==32이면 ULL 경로, 그 외에는 일반 DIV_ROUND_UP을 선택해 sector 크기를 계산합니다.',
  '0이 아닌 지원 divisor와 ll+d-1의 표현 범위를 확인합니다. 실제 32비트 빌드에서는 선택되는 ULL 경로와 64비트 빌드의 일반 식을 구분하며 divisor에 반복 부작용을 넣지 않습니다.',
  'ULL의 cast 위치와 SECTOR_T의 #if 분기를 읽으세요.',
  [('ULL 올림식의 큰 입력에서 먼저 확인할 조건은?','ll+d-1이 unsigned 64비트 범위 안인지다','unsigned이므로 수학 결과가 무조건 보존된다','unsigned wrap은 언어상 연산이지만 올림 몫 의미를 보존하지 않습니다. 표현 범위를 caller가 확인합니다.'),('BITS_PER_LONG==32의 SECTOR_T 선택은?','DIV_ROUND_UP_ULL이다','언제나 일반 DIV_ROUND_UP이다','헤더의 조건부 별칭을 확인합니다. 네이티브 32비트 실행과 조건 분기 모델 검사는 서로 다른 증거입니다.')],
  [('결과 단위','바이트나 sector 입력의 몫을 반환합니다. divisor 단위와 피제수 단위를 맞춰야 원하는 블록 수가 됩니다.'),('반복 인수','UP_ULL은 d를 덧셈과 내부 나눗셈 인수에 전달합니다. 값을 먼저 계산해 고정하는 습관이 필요합니다.')])
 lesson('임의 배수 올림·GNU statement expression과 divisor 임시','roundup',
  '2의 거듭제곱이 아닌 단위에도 크기를 올리는 나눗셈 계산을 배웁니다.',
  'roundup은 typeof(y) __y=y로 단위를 한 번 보관하고 ((x+(__y-1))/__y)*__y를 계산합니다. nonnegative 크기와 positive 단위에서 필요한 배수로 올립니다. GNU statement expression은 블록의 마지막 식을 값으로 사용하며 표준 C의 일반 괄호식과 다른 확장입니다.',
  'roundup(19U,6U)=24처럼 임의 배수에 사용합니다. 0 divisor와 합·곱의 표현 범위, x와 y의 usual arithmetic conversion을 확인합니다. 부호가 섞인 크기 계산은 먼저 형식을 맞춥니다.',
  '지역 __y와 마지막 나눗셈·곱셈 식을 읽으세요.',
  [('19를 6의 배수로 올리면?','24다','32다','19 이상 첫 6 배수는 24입니다. 임의 배수 식이므로 bit mask 전제를 쓰지 않습니다.'),('roundup에서 y를 지역 변수로 복사하는 이유는?','계산 중 단위를 한 번 평가해 재사용하기 위해서다','y를 항상 unsigned long으로 바꾸기 위해서다','지역 변수는 typeof(y) 형식입니다. 고정 폭 변환이 아니라 인수 평가와 재사용 구조를 제공합니다.')],
  [('적용 방향','같은 단위 배수로 커집니다. 이미 배수인 18은 18을 유지합니다.'),('도구 조건','Linux 빌드는 GNU C 확장을 사용합니다. 이 매크로 블록을 ISO C만 허용하는 컴파일러에 그대로 옮기면 문법 지원 문제가 생길 수 있습니다.')])
 lesson('임의 배수 내림·나머지를 빼는 계산','rounddown',
  '확보한 크기를 넘지 않는 임의 단위 배수를 나머지로 계산하는 방법을 배웁니다.',
  'rounddown은 typeof(x) __x=x로 입력을 한 번 보관하고 __x-(__x%y)를 반환합니다. nonnegative 크기와 positive 단위에서는 남은 나머지만 제거해 가장 가까운 아래 배수를 얻습니다. 음수에서는 C의 나머지 부호와 0 방향 나눗셈 때문에 일반 수학 floor 배수 설명을 그대로 확장하면 안 됩니다.',
  'rounddown(19U,6U)=18로 버퍼 구간을 제한합니다. 단위가 0이 아닌지 확인하고 signed 음수 범위가 필요하다면 요구한 반올림 방향에 맞는 별도 계산을 검토합니다.',
  '입력 임시와 % 결과를 빼는 마지막 식을 읽으세요.',
  [('19를 6의 배수로 내린 결과는?','18이다','16이다','19%6=1이므로 19-1=18입니다. 단위 6의 배수이며 거듭제곱 값 선택이 아닙니다.'),('signed -19와 양수 6에서 이 식을 수학 floor로 읽는 것은?','부호 있는 나머지 규약을 먼저 확인해야 한다','항상 -24를 보장한다','C는 음수 나눗셈을 0 방향으로 자릅니다. -19%6=-1이라 이 식은 -18로 계산되어 수학 floor 배수 -24와 다릅니다.')],
  [('평가 횟수','x는 지역 임시에 한 번 저장됩니다. y는 나머지 인수에서 한 번 등장합니다. 형식·부호 전제는 별도입니다.'),('용량 보존','양수 입력에서는 결과가 x를 넘지 않습니다. 확보한 바이트를 정해진 단위로 나누는 상황에 맞는 방향입니다.')])
 lesson('가까운 정수 나눗셈·부호 방향과 절반 경계','DIV_ROUND_CLOSEST',
  '양수와 음수의 나눗셈을 가장 가까운 정수로 보정하는 조건 분기를 배웁니다.',
  '매크로는 x와 divisor를 각 형식의 임시에 한 번 저장합니다. 둘 중 unsigned가 있거나 같은 부호이면 x+d/2를, 둘 다 signed이고 서로 다른 부호이면 x-d/2를 사용해 나눕니다. 지원 부호 조합에서 절반은 0에서 멀어지는 방향입니다. unsigned divisor와 음수 dividend 또는 unsigned dividend와 음수 divisor는 헤더가 undefined 결과로 명시합니다.',
  'DIV_ROUND_CLOSEST(-7,2)=-4와 (7,-2)=-4를 따라 읽습니다. divisor 0, 보정 합·차의 signed overflow, MIN/-1 나눗셈을 피하고 부호를 섞은 허용되지 않은 조합을 사용하지 않습니다.',
  'typeof(-1)>0 검사와 동일 부호 조건을 읽으세요.',
  [('두 signed 입력 -7과 2의 가까운 몫은?','-4다','-3이다','다른 부호에서는 -7-1=-8을 2로 나눕니다. 절반 경계를 0에서 멀어지는 방향으로 처리합니다.'),('음수 signed dividend와 unsigned divisor 조합은?','헤더가 결과를 undefined로 명시한다','항상 signed 계산을 강제해 안전하다','usual arithmetic conversion이 부호를 바꿀 수 있습니다. 주석의 지원 범위를 넘어선 조합을 일반 계약으로 설명하지 않습니다.')],
  [('표현 범위','가까운 값 보정은 오버플로 검출 API가 아닙니다. 큰 x에 d/2를 더하거나 빼는 중간 값도 범위 안이어야 합니다.'),('한 번 평가','__x와 __d에 값을 저장한 뒤 재사용합니다. 인수 부작용을 여러 번 실행하지 않는 구조와 산술 범위 안전성은 구분합니다.')])
 lesson('64비트 가까운 몫·반 divisor를 더한 임시','DIV_ROUND_CLOSEST_ULL',
  '64비트 unsigned 피제수의 가까운 몫을 별도 경로로 계산하는 방법을 배웁니다.',
  'DIV_ROUND_CLOSEST_ULL은 divisor를 typeof 임시에 저장하고 unsigned long long _tmp=x+d/2를 만든 뒤 do_div로 몫을 얻습니다. divisor는 원본 주석대로 32비트 숫자여야 하며 nonzero로 사용합니다. 음수용 보정 분기가 없고 중간 합의 unsigned wrap도 검출하지 않습니다.',
  '양수 unsigned 입력에서 DIV_ROUND_CLOSEST_ULL(7ULL,2U)=4를 사용합니다. 64비트 합 범위를 확인하고 지원되는 32비트 divisor 형식을 전달하며 signed 음수 입력의 의미를 추가하지 않습니다.',
  'divisor 임시·_tmp 생성과 마지막 몫 반환을 읽으세요.',
  [('7ULL을 2U로 가장 가까운 몫으로 나누면?','4다','3이다','7+1=8을 2로 나누므로 4입니다. 단순 내림 몫과 절반 보정을 구분합니다.'),('이 ULL 매크로의 divisor 폭 전제는?','32비트 숫자다','임의 128비트 숫자다','원본 주석은 divisor가 32비트 숫자여야 한다고 설명합니다. 피제수 ULL과 divisor 폭을 혼동하지 않습니다.')],
  [('평가','divisor는 지역 __d로 한 번 보관합니다. do_div가 바꾸는 것은 _tmp이며 원본 x 변수의 몫 대입이 아닙니다.'),('오류 반환 없음','divisor 0이나 합 wrap에 대한 errno가 없습니다. 유효한 산술 입력을 만드는 책임은 호출자에게 있습니다.')])
 lesson('분수 구조체·token pasting으로 여섯 형식 선언','__STRUCT_FRACT',
  '같은 분자·분모 구조를 여러 정수 폭으로 생성하는 전처리기 기술을 배웁니다.',
  '__STRUCT_FRACT(type)는 struct type##_fract 안에 __##type numerator와 denominator를 선언합니다. s8,u8,s16,u16,s32,u32 여섯 번 호출해 각 구조체를 만든 뒤 매크로를 undef합니다. ##은 토큰을 이어 실제 구조체 이름과 정수형 이름을 만드는 전처리기 연산입니다.',
  'struct u16_fract의 numerator=3,denominator=4처럼 원하는 저장 폭을 선택합니다. 구조체는 약분·분모 0 검사·정규화를 자동 실행하지 않으므로 값의 유효성과 분수 연산은 caller가 관리합니다.',
  'type##_fract와 __##type, 여섯 호출 및 undef를 읽으세요.',
  [('__STRUCT_FRACT(u16)이 만드는 구조체 이름은?','struct u16_fract다','struct type_fract라는 이름 하나다','전처리기 ##이 인수 u16과 _fract를 이어 구체적인 이름을 생성합니다.'),('denominator를 0으로 넣으면 자동 수정되는가?','아니며 선언은 저장 필드만 만든다','구조체가 생성될 때 항상 1로 고친다','매크로는 두 필드를 선언할 뿐입니다. 생성자나 분모 검사 함수가 없으며 값 유효성을 따로 관리합니다.')],
  [('부호와 폭','signed s8·s16·s32와 unsigned u8·u16·u32가 별도 형식입니다. 수치 범위와 음수 의미를 사용할 분수에 맞춥니다.'),('전처리 수명','undef는 이후 코드에서 생성 매크로 이름이 남지 않게 합니다. 생성된 여섯 구조체 선언은 그대로 남습니다.')])
 lesson('분수 곱셈 분해·몫과 나머지로 중간 크기 줄이기','mult_frac',
  '곱한 뒤 나눌 때 불필요한 큰 중간 곱을 줄이는 산술 변형을 배웁니다.',
  'mult_frac은 x,n,d를 각 형식 임시에 저장하고 q=x/d,r=x%d에서 q*n+r*n/d를 반환합니다. x=q*d+r이므로 분수 곱을 나눠 계산합니다. nonnegative 입력과 positive d에서 원래 x*n/d의 내림 결과와 같으면서 전체 x*n 중간 곱을 피합니다. 다만 q*n과 r*n까지 무조건 오버플로가 없어지는 것은 아닙니다.',
  '같은 적절한 unsigned 형식으로 mult_frac(10U,3U,4U)=7을 계산합니다. divisor 0과 남은 곱·합 범위를 확인하며 signed 음수의 0 방향 나눗셈으로 인한 다른 결과를 일반 보장하지 않습니다.',
  '세 임시, q·r 및 마지막 두 항을 읽으세요.',
  [('10×3/4를 이 분해로 계산하면?','q=2,r=2여서 6+1=7이다','q=2,r=2여서 6+2=8이다','나머지 항도 r*n/d=6/4=1로 나눕니다. 전체 내림 30/4=7과 같습니다.'),('mult_frac이 모든 오버플로를 자동 방지하는가?','아니며 두 곱과 합의 범위를 확인해야 한다','지원 숫자 폭을 자동으로 무한 확장한다','원본은 불필요한 전체 곱을 줄이는 변형입니다. q*n,r*n 및 결과 합의 표현 범위는 caller가 확인합니다.')],
  [('정확도','x/d부터 계산해 나머지를 버리는 단순식과 달리 r*n/d 항을 되돌려 일부 정밀도 손실을 막습니다.'),('signed 경계','signed 음수에서는 각각의 0 방향 나눗셈이 전체 식의 나눗셈과 같은 결과를 보장하지 않을 수 있습니다. 먼저 수치 계약과 형식을 정합니다.')])
 lesson('절댓값 매크로·형식 선택과 signed 변환','abs',
  'GNU 형식 선택이 절댓값의 반환형과 unsigned 입력에 영향을 주는 방식을 배웁니다.',
  'abs는 __abs_choose_expr를 long long,long,int,short,char 순서로 중첩합니다. __builtin_types_compatible_p로 signed·unsigned 대응형을 고르면 값을 signed type 임시에 변환해 부호를 검사합니다. plain char는 별도 분기로 signed char처럼 취급하고 반환은 char를 유지합니다. 지원되지 않는 형식의 끝 분기는 void입니다.',
  'abs(-7)=7처럼 범위 안의 signed 값을 사용합니다. unsigned의 큰 값은 signed 변환 정책을 먼저 확인해야 하며 원래 unsigned 숫자의 절댓값을 항상 보존한다고 가정하지 않습니다. int·long·long long 최솟값의 부호 반전은 표현 범위를 넘을 수 있습니다.',
  'choose_expr의 형식 검사와 __x<0?-__x:__x를 읽으세요.',
  [('unsigned 입력의 원본 처리 방식은?','대응 signed 형식으로 먼저 변환한다','항상 원래 unsigned 값을 그대로 반환한다','주석과 __abs_choose_expr의 signed 임시 선언을 확인합니다. 큰 unsigned 값의 변환 결과는 플랫폼 규약과 범위에 연결됩니다.'),('int 최솟값의 abs가 항상 int 양수로 표현되는가?','아니며 부호 반전의 표현 범위를 넘는다','반드시 int 최댓값+1을 안전 반환한다','최솟값의 양수 크기는 같은 signed int 범위 밖입니다. 범위 문제를 오류 반환으로 자동 처리하는 코드가 아닙니다.')],
  [('plain char','char 자체는 signed인지 unsigned인지 대상마다 다를 수 있지만 이 매크로는 signed char 임시로 취급한 뒤 char로 반환합니다.'),('계산 평가','선택된 형식 분기에서 인수를 한 번 임시에 저장합니다. GNU choose_expr와 형식 호환 검사는 runtime if와 구분합니다.')])
 lesson('두 값의 절대 차이·같은 형식 검사와 뺄셈 범위','abs_diff',
  '큰 값에서 작은 값을 빼는 계산에도 형식과 signed 범위 조건이 필요한 이유를 배웁니다.',
  'abs_diff는 두 값을 각 typeof 임시에 저장하고 &__a==&__b 비교로 같은 형식 조건을 드러냅니다. __a>__b이면 a-b, 아니면 b-a를 반환합니다. 같은 unsigned 형식은 순서를 맞춰 underflow를 피합니다. signed 극단값의 차이가 signed 범위를 넘으면 이 방식도 오버플로를 막지 못합니다.',
  'abs_diff(3U,10U)=7처럼 같은 형식으로 차이를 구합니다. signed -최대와 +최대 차이처럼 표현 폭보다 큰 결과가 필요한 경우 먼저 더 넓은 적절한 형식과 계산 계약을 마련합니다.',
  '두 임시의 주소 비교와 조건부 뺄셈을 읽으세요.',
  [('abs_diff(3U,10U)의 계산은?','10U-3U=7이다','3U-10U의 unsigned wrap이다','원본은 큰 값에서 작은 값을 빼므로 이 unsigned 예에서 underflow를 피합니다.'),('같은 signed 형식이면 극단값 차이도 항상 안전한가?','아니며 차이의 표현 범위를 별도 확인한다','같은 형식 검사만으로 overflow가 사라진다','형식 일치와 값 범위는 별도 조건입니다. 큰 양수와 큰 음수 차이는 같은 signed 형식에 들어가지 않을 수 있습니다.')],
  [('주소 비교','실제 데이터 주소가 같아야 한다는 runtime 조건이 아닙니다. 서로 다른 pointer 형식 비교를 컴파일 진단으로 드러내는 장치입니다.'),('형식 진단','진단을 오류로 취급하는 빌드 옵션에 따라 혼합 형식 사용이 막힐 수 있습니다. 매크로가 runtime 형식 변환 검증을 실행한다고 설명하지 않습니다.')])
 lesson('비율 스케일·곱의 높은 32비트로 구간 매핑','reciprocal_scale',
  '32비트 값을 특정 배열 구간에 비율로 배치하는 곱셈 스케일링 원리를 배웁니다.',
  'reciprocal_scale은 u64로 val*ep_ro를 계산해 32비트 오른쪽 shift하고 u32를 반환합니다. 즉 floor(val*ep_ro/2^32)입니다. ep_ro>0이면 입력 val이 u32 범위라 결과는 0..ep_ro-1 안에 있습니다. 두 u32의 곱은 u64에 들어갑니다. 나머지 val%ep_ro와 다른 매핑입니다.',
  'u32 값의 전체 구간을 ep_ro개 인덱스 구간으로 스케일할 때 사용합니다. ep_ro=0이면 계산은 0이지만 빈 배열 접근은 유효하지 않습니다. 작은 val은 0에 모일 수 있으며 난수 분포·공정성은 입력 분포에 연결됩니다.',
  'u64 cast 위치와 >>32를 읽으세요.',
  [('val=2^31,ep_ro=10의 스케일 결과는?','5다','val%10만을 반환한다','전체 32비트 구간의 절반이므로 곱을 2^32로 나눈 결과는 5입니다. modulo와 다른 비율 매핑입니다.'),('ep_ro=0일 때 반환 0을 배열 인덱스로 써도 되는가?','빈 구간에는 유효한 인덱스가 없으므로 안 된다','0 반환은 배열 길이를 자동으로 1로 늘린다','산술 결과와 자료구조 접근 유효성은 다릅니다. caller는 길이가 0이 아닌지 확인해야 합니다.')],
  [('상한 증명','val<=2^32-1이므로 양수 ep_ro의 곱은 ep_ro*2^32보다 작습니다. 바닥 나눗셈 결과가 ep_ro 미만인 이유입니다.'),('비교','reciprocal_divide는 고정 divisor로 정확한 몫을 만드는 별도 API입니다. 여기의 endpoint 스케일링과 목적·결과를 구분합니다.')])
 lesson('정수 수학 선언 연결·sqrt64의 조건부 본문','int_sqrt64',
  '공개 수학 헤더가 정수 거듭제곱·제곱근 구현과 빌드 폭을 연결하는 방법을 배웁니다.',
  'math.h는 int_pow(u64,unsigned int)와 int_sqrt(unsigned long)를 선언합니다. BITS_PER_LONG<64에서는 int_sqrt64(u64)의 외부 선언을, 64비트 long에서는 int_sqrt(x)를 u32로 변환하는 inline 본문을 제공합니다. u64 제곱근의 최대 바닥값은 2^32-1이라 u32 반환에 들어갑니다.',
  '입력 폭에 맞는 API로 호출하고 lib/math/int_pow.c·int_sqrt.c의 수업과 연결합니다. long32 구성의 별도 u64 본문과 long64의 inline 호출을 같은 함수 중복 구현이라고 혼동하지 않습니다.',
  '세 선언과 BITS_PER_LONG 조건을 C 구현 파일과 연결하세요.',
  [('u64 최댓값의 바닥 제곱근이 u32에 들어가는 이유는?','2^32보다 작아 최대 2^32-1이기 때문이다','입력을 먼저 u32로 자르기 때문이다','sqrt(2^64-1)<2^32이므로 바닥값이 u32에 들어갑니다. long64 경로는 원래 u64 입력을 long으로 계산합니다.'),('long64 빌드에서 int_sqrt64 연결 방식은?','inline에서 int_sqrt(x)를 호출한다','항상 lib의 long32 조건 본문을 중복 컴파일한다','헤더 #else의 inline 본문을 확인합니다. lib의 별도 u64 본문은 BITS_PER_LONG<64에서만 포함됩니다.')],
  [('정수 결과','제곱근은 소수를 반환하지 않으며 바닥값입니다. int_pow는 u64 거듭제곱이고 표현 범위를 넘는 결과를 arbitrary precision으로 확장하지 않습니다.'),('헤더 전체','types·asm/div64·uapi/kernel include와 include guard, private mask·abs 형식 생성·undef, 모든 rounding/division/fraction/scale API 및 조건부 선언을 각 수업에서 연결합니다.')])
